import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIODeviceClosed

PINS = [2, 3, 4]
INTERVAL = 60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = OutputDevice(pin)
                devices.append(dev)
            except GPIODeviceError as exc:
                print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        while _running:
            for dev in devices:
                try:
                    dev.toggle()
                    state = "HIGH" if dev.is_active else "LOW"
                    print(f"GPIO {dev.pin.number} -> {state}")
                except GPIODeviceClosed:
                    print(f"Error: device on GPIO {dev.pin.number} closed unexpectedly.", file=sys.stderr)
                    return 1

            for _ in range(INTERVAL):
                if not _running:
                    break
                time.sleep(1)

    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

