import signal
import sys
import time

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
TIMEOUT_S = 1.0
POLL_INTERVAL_S = 1.0
MAX_INIT_RETRIES = 5
INIT_RETRY_DELAY_S = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _open_serial(port, baud, timeout):
    for attempt in range(1, MAX_INIT_RETRIES + 1):
        try:
            ser = serial.Serial(port, baud, timeout=timeout)
            print(f"Serial port {port} opened at {baud} baud.")
            return ser
        except serial.SerialException as e:
            print(f"Attempt {attempt}/{MAX_INIT_RETRIES}: could not open {port}: {e}")
            if attempt < MAX_INIT_RETRIES:
                time.sleep(INIT_RETRY_DELAY_S)
    return None

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = _open_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT_S)
    if ser is None:
        print(f"Failed to open {SERIAL_PORT} after {MAX_INIT_RETRIES} attempts.")
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
                if raw:
                    line = raw.decode('ascii', errors='replace').strip()
                    if line:
                        print(line)
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                break
            except OSError as e:
                print(f"I/O error: {e}")
                break

            time.sleep(POLL_INTERVAL_S)
    finally:
        try:
            ser.close()
            print("Serial port closed.")
        except Exception:
            pass

if __name__ == '__main__':
    main()

