import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
VALIDITY_CHECK = lambda data: data is not None and len(data) > 0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_sensor_data(serial_connection):
    try:
        raw = serial_connection.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected read error: {e}", file=sys.stderr)
        return None

def process_data(data):
    if not VALIDITY_CHECK(data):
        return
    print(f'Sensor Reading: {data}')

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=READ_TIMEOUT
        )
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            sensor_data = read_sensor_data(serial_connection)
            if sensor_data is not None:
                process_data(sensor_data)
            time.sleep(0.5)
    finally:
        if serial_connection.is_open:
            serial_connection.close()
        print("Serial port closed. Exiting.")

if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PIN = 17
CYCLES = 5
DELAY = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        device = OutputDevice(PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO {PIN}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error initializing GPIO {PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(CYCLES):
            if not _running:
                print("Interrupted before cycle", i)
                break

            device.on()
            print(f"Cycle {i}: GPIO {PIN} -> HIGH")

            if i < CYCLES - 1 and _running:
                time.sleep(DELAY)

            if not _running:
                break

            device.off()
            print(f"Cycle {i}: GPIO {PIN} -> LOW")

            if i < CYCLES - 1 and _running:
                time.sleep(DELAY)

        if _running:
            print("GPIO cleanup completed.")
        else:
            print("GPIO cleanup interrupted.")

    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)

    finally:
        try:
            device.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

