    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PWM_PINS:
            dev = PWMOutputDevice(pin, frequency=1000)
            dev.value = 0.0
            devices.append(dev)
            print(f"PWM initialized on GPIO {pin} (BCM) at 1 kHz, duty 0%")

        while _running:
            try:
                raw = input("Enter duty cycle (0-100): ").strip()
            except EOFError:
                break
            if not raw:
                continue
            try:
                duty = float(raw)
            except ValueError:
                print("Invalid input: not a number.")
                continue
            if not (0.0 <= duty <= 100.0):
                print("Invalid input: must be between 0 and 100.")
                continue
            for dev in devices:
                dev.value = duty / 100.0
                print(f"GPIO {dev.pin.number} -> {duty:.1f}%")
            break

    except GPIOZeroError as e:
        print(f"GPIO error: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        for dev in devices:
            try:
                dev.value = 0.0
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

