import signal
import sys
import time

import serial

PORT = "/dev/serial0"
BAUD = 9600
TIMEOUT = 2.0
MAX_RETRIES = 3
RETRY_DELAY = 0.5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def open_serial(port, baud, timeout):
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as exc:
        print(f"Error: cannot open {port}: {exc}", file=sys.stderr)
        return None

def read_line(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error: serial read failed: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        return raw.decode("utf-8", errors="replace").strip()
    except Exception as exc:
        print(f"Error: decode failed: {exc}", file=sys.stderr)
        return None

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = open_serial(PORT, BAUD, TIMEOUT)
    if ser is None:
        sys.exit(1)

    try:
        for attempt in range(1, MAX_RETRIES + 1):
            if not _running:
                break
            line = read_line(ser)
            if line:
                print(line)
                break
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
        else:
            print("Error: no data received from device after retries.", file=sys.stderr)
            sys.exit(1)
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

