import signal
import sys
import time
import board
import adafruit_dht

# --- Configuration -----------------------------------------------------------
PIN_MAP = {
    4:  board.D4,
    5:  board.D5,
    17: board.D17,
    23: board.D23,
}

INTERVAL_SECONDS = 60
MAX_RETRIES = 3
RETRY_DELAY = 2.0

# --- Globals for cleanup -----------------------------------------------------
_running = True
_devices = []

def _handle_signal(signum, frame):
    global _running
    _running = False

def _cleanup():
    for dev in _devices:
        try:
            dev.exit()
        except Exception:
            pass
    _devices.clear()

def main():
    global _devices

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialise every pin; skip any that fail so we can continue on others.
    for bcm_pin, board_pin in PIN_MAP.items():
        try:
            dev = adafruit_dht.DHT22(board_pin, use_pulseio=False)
            _devices.append(dev)
            print(f"[init] DHT22 on GPIO {bcm_pin} (board.{board_pin.name})")
        except Exception as exc:
            print(f"[init] GPIO {bcm_pin}: {exc}", file=sys.stderr)

    if not _devices:
        print("No DHT22 devices initialised; exiting.", file=sys.stderr)
        return 1

    print("Starting DHT22 monitoring (Ctrl-C to stop)...")

    while _running:
        for dev in list(_devices):
            if not _running:
                break

            bcm_pin = None
            for p, d in zip(PIN_MAP.values(), _devices):
                if d is dev:
                    for k, v in PIN_MAP.items():
                        if v is p:
                            bcm_pin = k
                            break
                    break

            if bcm_pin is None:
                continue

            for attempt in range(1, MAX_RETRIES + 1):
                if not _running:
                    break

                try:
                    temperature = dev.temperature
                    humidity = dev.humidity

                    # CircuitPython DHT22 returns None on a bad checksum.
                    if temperature is None or humidity is None:
                        raise RuntimeError("Sensor returned None (checksum error)")

                    # Sanity range checks (DHT22: -40–80 °C, 0–100 %RH)
                    if not (-40.0 <= temperature <= 80.0):
                        raise RuntimeError(f"Temperature out of range: {temperature}")
                    if not (0.0 <= humidity <= 100.0):
                        raise RuntimeError(f"Humidity out of range: {humidity}")

                    print(f"GPIO {bcm_pin}: {temperature:.1f} °C  {humidity:.1f} %RH")
                    break

                except RuntimeError as exc:
                    # Common transient errors: "Checksum failed", "A full buffer was not returned",
                    # "A full buffer was not returned", "Sensor returned None".
                    print(f"GPIO {bcm_pin}: read attempt {attempt}/{MAX_RETRIES} failed: {exc}",
                          file=sys.stderr)
                    if attempt < MAX_RETRIES:
                        time.sleep(RETRY_DELAY)
                except Exception as exc:
                    # Unexpected error (e.g. device disconnected) — log and continue.
                    print(f"GPIO {bcm_pin}: unexpected error: {exc}", file=sys.stderr)
                    break

        if _running:
            # Sleep in small increments so signals are caught promptly.
            slept = 0.0
            while _running and slept < INTERVAL_SECONDS:
                time.sleep(0.5)
                slept += 0.5

    print("\nShutting down...")
    _cleanup()
    print("Done.")
    return 0

if __name__ == "__main__":
    sys.exit(main())

