import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
POLL_INTERVAL = 1.0
MAX_RETRIES = 3

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_sensor_data(serial_connection):
    try:
        raw = serial_connection.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        parts = line.split(',')
        if len(parts) != 2:
            return None
        temperature, humidity = parts
        try:
            temperature = float(temperature)
            humidity = float(humidity)
        except ValueError:
            return None
        if not (-40.0 <= temperature <= 80.0):
            return None
        if not (0.0 <= humidity <= 100.0):
            return None
        return temperature, humidity
    except serial.SerialException:
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            timeout=READ_TIMEOUT
        )
    except serial.SerialException as e:
        print(f"Error: Could not open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        while running:
            reading = None
            for attempt in range(1, MAX_RETRIES + 1):
                reading = read_sensor_data(serial_connection)
                if reading is not None:
                    break
                if attempt < MAX_RETRIES:
                    time.sleep(0.1)
            if reading is None:
                print("Error: Failed to read valid sensor data after retries.", file=sys.stderr)
                break
            temperature, humidity = reading
            print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
            time.sleep(POLL_INTERVAL)
    finally:
        serial_connection.close()
        print("Serial port closed.")

