import signal
import sys
import time

from gpiozero import AngularServo
from gpiozero.pins.lgpio import LGPIOFactory

# Use the modern lgpio backend (libgpiod-based) for reliable, modern access.
try:
    factory = LGPIOFactory()
except Exception as exc:
    print(f"Failed to initialize lgpio factory: {exc}", file=sys.stderr)
    sys.exit(1)

# SG90 servo pin assignments (BCM numbering).
SERVO_PINS = (4, 18)

# gpiozero AngularServo uses min_pulse_width and max_pulse_width to map
# -90°..90° to the 1ms..2ms pulse widths typical for an SG90.
servos = []

try:
    for pin in SERVO_PINS:
        try:
            servo = AngularServo(
                pin,
                min_angle=-90,
                max_angle=90,
                min_pulse_width=1 / 1000,
                max_pulse_width=2 / 1000,
                pin_factory=factory,
            )
            servos.append(servo)
        except Exception as exc:
            print(f"Failed to initialize servo on GPIO {pin}: {exc}", file=sys.stderr)
            raise

    # Graceful shutdown flag.
    running = True

    def handle_signal(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    # Sweep -90°..90°..-90° every 5 seconds.
    while running:
        for servo in servos:
            try:
                servo.angle = -90
                print(f"Servo on GPIO {servo.pin.number} set to -90 degrees")
            except Exception as exc:
                print(f"Error setting servo to -90: {exc}", file=sys.stderr)
        time.sleep(0.5)
        if not running:
            break
        for servo in servos:
            try:
                servo.angle = 90
                print(f"Servo on GPIO {servo.pin.number} set to 90 degrees")
            except Exception as exc:
                print(f"Error setting servo to 90: {exc}", file=sys.stderr)
        time.sleep(0.5)
        if not running:
            break
        for servo in servos:
            try:
                servo.angle = -90
                print(f"Servo on GPIO {servo.pin.number} set to -90 degrees")
            except Exception as exc:
                print(f"Error setting servo to -90: {exc}", file=sys.stderr)
        time.sleep(0.5)

except Exception as exc:
    print(f"Fatal error: {exc}", file=sys.stderr)

finally:
    # Release all servo resources cleanly.
    for servo in servos:
        try:
            servo.close()
        except Exception:
            pass
    try:
        factory.close()
    except Exception:
        pass
    print("GPIO cleanup completed.")

