import signal
import sys
import time

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 115200
READ_TIMEOUT = 1.0
LOOP_DELAY = 0.05
MAX_INIT_RETRIES = 5
INIT_RETRY_DELAY = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _open_serial(port, baud, timeout):
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        ser.reset_input_buffer()
        ser.reset_output_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def _read_serial(ser):
    try:
        line = ser.readline()
        if line:
            decoded = line.decode('utf-8', errors='replace').strip()
            if decoded:
                print(decoded)
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    for attempt in range(1, MAX_INIT_RETRIES + 1):
        ser = _open_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
        if ser is not None:
            break
        if attempt < MAX_INIT_RETRIES:
            print(f"Retrying serial connection ({attempt}/{MAX_INIT_RETRIES})...", file=sys.stderr)
            time.sleep(INIT_RETRY_DELAY)

    if ser is None:
        print("Failed to open serial port after retries.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            _read_serial(ser)
            time.sleep(LOOP_DELAY)
    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.", file=sys.stderr)

if __name__ == '__main__':
    main()

