READ_INTERVAL_S = 5
MAX_INIT_RETRIES = 3
MAX_READ_RETRIES = 3

# --- Globals for cleanup -----------------------------------------------------
_running = True
_devices = []


def _handle_signal(signum, frame):
    global _running
    _running = False


def _init_device(pin_num):
    """Create a DHT22 reader on the given BCM pin; return None on failure."""
    try:
        return adafruit_dht.DHT22(PIN_MAP[pin_num], use_pulseio=False)
    except Exception as exc:
        print(f"[ERROR] Failed to initialise DHT22 on GPIO {pin_num}: {exc}",
              file=sys.stderr)
        return None


def _read_device(device, pin_num):
    """Return (temperature, humidity) or (None, None) on failure."""
    for attempt in range(1, MAX_READ_RETRIES + 1):
        try:
            temperature = device.temperature
            humidity = device.humidity

            # CircuitPython DHT22 returns None on a bad checksum / timing glitch
            if temperature is None or humidity is None:
                raise RuntimeError("Sensor returned None (checksum / timing error)")

            # Sanity-check ranges per the DHT22 datasheet
            if not (-40.0 <= temperature <= 80.0):
                raise RuntimeError(f"Temperature out of range: {temperature}")
            if not (0.0 <= humidity <= 100.0):
                raise RuntimeError(f"Humidity out of range: {humidity}")

            return temperature, humidity

        except Exception as exc:
            print(f"[WARN] Read attempt {attempt}/{MAX_READ_RETRIES} "
                  f"failed on GPIO {pin_num}: {exc}", file=sys.stderr)
            if attempt < MAX_READ_RETRIES:
                time.sleep(2.0)

    print(f"[ERROR] GPIO {pin_num}: failed to read after "
          f"{MAX_READ_RETRIES} attempts.", file=sys.stderr)
    return None, None


def main():
    global _devices

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialise every pin; skip any that fail
    for pin_num in PIN_MAP:
        device = _init_device(pin_num)
        if device is None:
            continue
        _devices.append(device)

    if not _devices:
        print("[ERROR] No DHT22 devices could be initialised. "
              "Check wiring and that the sensor is present.", file=sys.stderr)
        sys.exit(1)

    print("DHT22 monitoring started. Press Ctrl+C to stop.")

    try:
        while _running:
            for device in _devices:
                if not _running:
                    break

                # Map the device object back to a pin number for reporting
                # (board.Dx objects are not hashable, so we keep a list of
                # device objects and pin numbers separately)
                pin_num = next((k for k, v in PIN_MAP.items()
                                if v == device.pin.number), None)
                if pin_num is None:
                    pin_num = "?"

                temperature, humidity = _read_device(device, pin_num)

                if temperature is not None and humidity is not None:
                    print(f"GPIO {pin_num}: "
                          f"Temperature = {temperature:.1f} °C  "
                          f"Humidity = {humidity:.1f} %")
                else:
                    print(f"GPIO {pin_num}: read failed.")

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < READ_INTERVAL_S:
                time.sleep(0.2)
                slept += 0.2

    finally:
        for device in _devices:
            try:
                device.exit()
            except Exception:
                pass
        print("\nCleanup complete. Exiting.")


if __name__ == "__main__":
    main()

