import time
import signal
import sys
import logging

from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("picam2_capture")

INTERVAL_S = 0.1
MAX_INIT_RETRIES = 3
INIT_RETRY_DELAY_S = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    log.info("Signal %s received – shutting down …", signum)
    _running = False

def init_camera():
    for attempt in range(1, MAX_INIT_RETRIES + 1):
        try:
            cam = Picamera2()
            cam.configure("still")
            cam.start()
            log.info("Camera initialised on attempt %d.", attempt)
            return cam
        except Exception as exc:
            log.warning("Camera init attempt %d/%d failed: %s", attempt, MAX_INIT_RETRIES, exc)
            if attempt < MAX_INIT_RETRIES:
                time.sleep(INIT_RETRY_DELAY_S)
    return None

def capture_and_save(cam, path):
    try:
        cam.capture_file(path)
        log.info("Image saved to %s", path)
        return True
    except Exception as exc:
        log.error("Capture/save failed: %s", exc)
        return False

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    cam = init_camera()
    if cam is None:
        log.error("Camera unavailable after %d attempts.", MAX_INIT_RETRIES)
        sys.exit(1)

    try:
        while _running:
            if not capture_and_save(cam, "image.jpg"):
                log.warning("Capture rejected – continuing.")
            time.sleep(INTERVAL_S)
    finally:
        try:
            cam.stop()
        except Exception as exc:
            log.warning("Error stopping camera: %s", exc)
        log.info("Clean exit.")

if __name__ == "__main__":
    main()

