    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
    except serial.SerialException as e:
        print(f"Failed to open {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected init error: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            data = read_sensor_data(ser)
            if data is not None:
                process_data(data)
            time.sleep(0.5)
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == "__main__":
