# Global flag for graceful shutdown
_running = True

def _handle_signal(signum, frame):
    """Signal handler for graceful shutdown."""
    global _running
    _running = False

def main():
    global _running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize DHT22 sensors
    sensors = []
    for pin in DHT_PINS:
        try:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            sensors.append(sensor)
        except Exception as e:
            print(f"Failed to initialize DHT22 on pin {pin}: {e}", file=sys.stderr)
            # Continue with remaining sensors

    if not sensors:
        print("No DHT22 sensors initialized. Exiting.", file=sys.stderr)
        sys.exit(1)

    print("DHT22 sensors initialized. Press Ctrl+C to stop.")

    try:
        while _running:
            for sensor in sensors:
                try:
                    temperature = sensor.temperature
                    humidity = sensor.humidity

                    if temperature is not None and humidity is not None:
                        print(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")
