import signal
import sys
import time

from gpiozero import PWMOutputDevice

PWM_PINS = (4, 17)
VALID_RANGE = (0.0, 100.0)
INTERVAL_S = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _clamp(value, lo, hi):
    return max(lo, min(hi, value))


def _is_valid(value):
    return VALID_RANGE[0] <= value <= VALID_RANGE[1]


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PWM_PINS:
            dev = PWMOutputDevice(pin)
            dev.value = 0.0
            devices.append(dev)

        while _running:
            try:
                raw = input("Enter PWM value (0-100): ").strip()
            except EOFError:
                break

            try:
                value = float(raw)
            except ValueError:
                print("Invalid input: not a number.", file=sys.stderr)
                continue

            if not _is_valid(value):
                print(f"Invalid input: must be between {VALID_RANGE[0]} and {VALID_RANGE[1]}.", file=sys.stderr)
                continue

            value = _clamp(value, VALID_RANGE[0], VALID_RANGE[1])
            duty = value / 100.0

            for dev in devices:
                dev.value = duty

            print(f"PWM set to {value:.1f}% on pins {PWM_PINS}")

            time.sleep(INTERVAL_S)

    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
    finally:
        for dev in devices:
            try:
                dev.value = 0.0
                dev.close()
            except Exception:
                pass
        print("GPIO released.")


if __name__ == "__main__":
    main()

