import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PINS = (12, 18)

def apply_state(pin: int, state: int) -> None:
    """Set a GPIO pin to a validated logic level and report it."""
    if state not in (0, 1):
        print(f"Error: state {state} is not valid (must be 0 or 1).", file=sys.stderr)
        return
    try:
        with OutputDevice(pin) as dev:
            dev.value = state
            print(f"GPIO {pin} set to {state}")
    except GPIOZeroError as exc:
        print(f"Error setting GPIO {pin}: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error setting GPIO {pin}: {exc}", file=sys.stderr)

def main() -> int:
    if len(sys.argv) != 3:
        print("Usage: python script.py <pin> <state>", file=sys.stderr)
        return 1

    try:
        pin = int(sys.argv[1])
        state = int(sys.argv[2])
    except ValueError:
        print("Error: pin and state must be integers.", file=sys.stderr)
        return 1

    if pin not in PINS:
        print(f"Error: pin {pin} is not in the allowed set {PINS}.", file=sys.stderr)
        return 1

    apply_state(pin, state)
    return 0

if __name__ == "__main__":
    signal.signal(signal.SIGINT, lambda *_: sys.exit(130))
    sys.exit(main())

