def _handle_signal(signum, frame):
    global _running
    _running = False


def read_sensor(sensor):
    """Return a valid float reading, or None if the read is invalid."""
    try:
        value = sensor.value
    except DeviceClosed:
        print("Error: device closed unexpectedly.", file=sys.stderr)
        return None
    except Exception as exc:
        print(f"Error reading sensor: {exc}", file=sys.stderr)
        return None

    if not isinstance(value, (int, float)):
        print(f"Error: non-numeric sensor reading: {value!r}", file=sys.stderr)
        return None

    if not (0.0 <= value <= 1.0):
        print(f"Error: sensor reading out of range: {value}", file=sys.stderr)
        return None

    return float(value)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = PWMOutputDevice(PWM_PIN)
