        sys.exit(1)
    except Exception as exc:
        print(f"Error: unexpected failure initializing GPIO {PWM_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            reading = read_sensor(sensor)
            if reading is not None:
                print(f"Sensor reading: {reading:.4f}")
            else:
                print("Sensor reading: invalid", file=sys.stderr)

            for _ in range(INTERVAL_S):
                if not _running:
                    break
                time.sleep(1)
