import time
import signal
import sys
from w1thermsensor import W1ThermSensor, SensorNotReadyError, NoSensorFoundError

# 1-Wire data pin connected to GPIO 4 (BCM)
DATA_PIN = 4
# 1-Wire data pin connected to GPIO 17 (BCM)
DATA_PIN_2 = 17

# Graceful shutdown flag
_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize sensors; exit on fatal hardware errors
    try:
        sensor1 = W1ThermSensor(W1ThermSensor.THERM_SENSOR_DS18B20, DATA_PIN)
    except NoSensorFoundError:
        print(f"Error: No DS18B20 sensor found on GPIO {DATA_PIN}. Check wiring.", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error initializing sensor on GPIO {DATA_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        sensor2 = W1ThermSensor(W1ThermSensor.THERM_SENSOR_DS18B20, DATA_PIN_2)
    except NoSensorFoundError:
        print(f"Warning: No DS18B20 sensor found on GPIO {DATA_PIN_2}. Will skip readings from this pin.", file=sys.stderr)
        sensor2 = None
    except Exception as e:
        print(f"Error initializing sensor on GPIO {DATA_PIN_2}: {e}", file=sys.stderr)
        sensor2 = None

    print("DS18B20 Temperature Monitor Started")
    print("Press Ctrl+C to stop.\n")

    try:
        while _running:
            try:
                temp_c = sensor1.get_temperature()
                # Validate reading: reject None or NaN
                if temp_c is None or temp_c != temp_c:
                    print("Error: Invalid reading from GPIO 4 (None or NaN).")
                else:
                    print(f"GPIO 4 - Temperature: {temp_c:.2f} °C")
            except SensorNotReadyError:
                print("Error: GPIO 4 sensor not ready (conversion in progress).")
            except Exception as e:
                print(f"Error reading GPIO 4: {e}")

            if sensor2 is not None:
                try:
                    temp_c2 = sensor2.get_temperature()
                    if temp_c2 is None or temp_c2 != temp_c2:
                        print("Error: Invalid reading from GPIO 17 (None or NaN).")
                    else:
                        print(f"GPIO 17 - Temperature: {temp_c2:.2f} °C")
                except SensorNotReadyError:
                    print("Error: GPIO 17 sensor not ready (conversion in progress).")
                except Exception as e:
                    print(f"Error reading GPIO 17: {e}")

            # Wait 5 seconds, but wake up every 0.1 s to check _running flag
            for _ in range(50):
                if not _running:
                    break
                time.sleep(0.1)

    finally:
        # w1thermsensor does not require explicit resource release;
        # the Linux kernel handles it on process exit.
        print("\nExiting program.")

if __name__ == "__main__":
    main()

import time
import signal
import sys
import logging

from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("picam2_capture")

INTERVAL_S = 2.0
MAX_INIT_RETRIES = 3
INIT_RETRY_DELAY = 2.0

_running = True

def _handle_signal(signum, frame):
    global _running
    log.info("Signal %s received, shutting down...", signum)
    _running = False

def init_camera():
    for attempt in range(1, MAX_INIT_RETRIES + 1):
        try:
            cam = Picamera2()
            cam.configure("still")
            cam.start()
            log.info("Camera initialized on attempt %d.", attempt)
            return cam
        except Exception as exc:
            log.warning("Camera init attempt %d failed: %s", attempt, exc)
            if attempt < MAX_INIT_RETRIES:
                time.sleep(INIT_RETRY_DELAY)
    return None

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    cam = init_camera()
    if cam is None:
        log.error("Camera initialization failed after %d attempts.", MAX_INIT_RETRIES)
        sys.exit(1)

    try:
        while _running:
            try:
                cam.capture_file("image.jpg")
                log.info("Image saved to image.jpg")
            except Exception as exc:
                log.error("Capture failed: %s", exc)

            if _running:
                time.sleep(INTERVAL_S)
    finally:
        try:
            cam.stop()
        except Exception:
            pass
        try:
            cam.close()
        except Exception:
            pass
        log.info("Camera released. Exiting.")

if __name__ == "__main__":
    main()

