import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

DEVICE_PIN = 18
VALIDITY_CHECK = True
TIMEOUT_SECONDS = 5.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def apply_state(device, state):
    if state:
        device.on()
        return True
    device.off()
    return False


def read_state(device):
    return bool(device.value)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        device = OutputDevice(DEVICE_PIN)
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize GPIO {DEVICE_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        print(f"GPIO {DEVICE_PIN} initialized as output.")

        if not _running:
            return

        print("Setting state to HIGH...")
        apply_state(device, True)
        print("State set to HIGH.")

        if not _running:
            return

        if VALIDITY_CHECK:
            print("Reading state...")
            try:
                read_state(device)
                print("State read successfully.")
            except GPIOZeroError as exc:
                print(f"Error: failed to read GPIO {DEVICE_PIN}: {exc}", file=sys.stderr)
                sys.exit(1)

        if not _running:
            return

        print("Setting state to LOW...")
        apply_state(device, False)
        print("State set to LOW.")

        if not _running:
            return

        if VALIDITY_CHECK:
            print("Reading state...")
            try:
                read_state(device)
                print("State read successfully.")
            except GPIOZeroError as exc:
                print(f"Error: failed to read GPIO {DEVICE_PIN}: {exc}", file=sys.stderr)
                sys.exit(1)

        print("GPIO cleanup completed.")

    except GPIOZeroError as exc:
        print(f"Error: GPIO operation failed: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: unexpected failure: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        try:
            device.close()
        except DeviceClosed:
            pass
        except Exception:
            pass


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PWM_PINS = [5, 6, 13, 17, 18, 22, 23, 24, 27]

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PWM_PINS:
            try:
                dev = PWMOutputDevice(pin, frequency=1000, initial_value=0.0)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize PWM on GPIO {pin}: {exc}", file=sys.stderr)
                return 1

        while _running:
            for dev in devices:
                try:
                    value = dev.value
                except DeviceClosed:
                    print(f"Error: device on GPIO {dev.pin.number} closed unexpectedly.", file=sys.stderr)
                    return 1

                if not (0.0 <= value <= 1.0):
                    print(f"Error: unexpected value {value} on GPIO {dev.pin.number}.", file=sys.stderr)
                    return 1

                print(f"GPIO {dev.pin.number}: {value:.4f}")

            time.sleep(1)

    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass

    return 0


if __name__ == "__main__":
    sys.exit(main())

