import signal
import sys
import time

import adafruit_dht
from board import D4

# Global handle so the signal handler can release it.
_sensor = None


def _cleanup(signum=None, frame=None):
    """Release the DHT22 hardware resource on exit or signal."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None
    if signum is not None:
        sys.exit(0)


def main():
    global _sensor

    # Register signal handlers for graceful shutdown.
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    # Initialize the DHT22 on GPIO 4 (BCM).
    try:
        _sensor = adafruit_dht.DHT22(D4, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on GPIO 4: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for cycle in range(1, 4):
            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is not None and humidity is not None:
                    print(
                        f"Cycle {cycle}: Temperature = {temperature:.1f} °C, "
                        f"Humidity = {humidity:.1f} %"
                    )
                else:
                    print(f"Cycle {cycle}: Sensor returned None")
            except RuntimeError as exc:
                # DHT22 checksum / timing errors are common; report and continue.
                print(f"Cycle {cycle}: Read error: {exc}")

            time.sleep(2.0)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

